// 1. Safely navigate the object using optional chaining (?.)
const rawContent =  $input.first().json.document.pageContent;
const rawSource =  $input.first().json.document.metadata.source;
const rawAuthor = $input.first().json.document.metadata.author;

let ragResult;
let source;
let author;


if (rawContent !== null && rawContent !== undefined) {
    ragResult = String(rawContent)

        .replace(/[\r\n]+/g, ' ')
        // B. Replace tabs (\t) and special unicode whitespaces with a standard space
        .replace(/[\t\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+/g, ' ')

        .replace(/ {2,}/g, ' ')
        // D. Clean up any trailing/leading spaces left over
        .trim();
} else {
    ragResult = "not found";
}

// 3. Handle the source
source = (rawSource !== null && rawSource !== undefined) ? rawSource : "not found";
author = (rawAuthor !== null && rawAuthor !== undefined) ? rawAuthor : "not found";

// 4. Final check: if either is "not found", set both to "not found"
if (ragResult === "not found" || source === "not found") {
    ragResult = "not found";
    source = "not found";
}

return { rag_result: ragResult, source: source, author: author };
